mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T1.PORTFOLIO_ID portfolioId, T4.ASSET_TYPE1 assetType1,
T4.ASSET_TYPE1 type9, T4.ASSET_TYPE_10 type10, T4.ASSET_TYPE_11 type11,
T2.PORTFOLIO_NAME portfolioName, T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.PS ps, T1.ENTRUST_AMT entrustAmt, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate,
T1.INV_MANAGER_ID invManagerId, NVL(T5.FINISH_AMT,0) finishAmt, round(NVL(T5.FINISH_AMT,0)/T1.ENTRUST_AMT,4)*100 transactioncom, T1.REMARK remark FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID INNER JOIN ETR_ENTRUST_ADD T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(NVL(FINISH_AMT,0)) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T2.PORTFOLIO_ID = T6.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
AND (T2.PORTFOLIO_ID IN
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
#{prot}
)
AND T4.ASSET_TYPE1 in
#{item}
AND T4.ASSET_TYPE1 in
#{item}
AND T4.ASSET_TYPE_10 in
#{item}
AND T4.ASSET_TYPE_11 in
#{item}
AND T1.CCY in
#{item}
AND (T3.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%')) OR T3.FINPROD_NAME like concat('%',concat(#{finprodId},'%')))
AND T1.PS=#{ps}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE2}
order by T1.ENTRUST_ID DESC

SELECT T1.PORTFOLIO_ID code, T1.PORTFOLIO_ID name, T1.PORTFOLIO_NAME shortName, T1.PORTFOLIO_ID hidCode FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
T1.PORTFOLIO_ID like concat('%',concat(#{param},'%')) or T1.PORTFOLIO_NAME like concat('%',concat(#{param},'%'))
AND T1.PORTFOLIO_TYPE IN (#{portType}, #{portType1})

SELECT FINPROD_MARKET_ID code, FINPROD_MARKET_ID name, FINPROD_NAME shortName, FINPROD_ID hidCode FROM FIN_PRODUCT
FINPROD_TYPE2 = #{product}
and (FINPROD_MARKET_ID like concat('%',concat(#{param},'%')) or FINPROD_NAME like concat('%',concat(#{param},'%')))

SELECT T1.PORTFOLIO_ID id, T1.PORTFOLIO_NAME text FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
T1.PORTFOLIO_ID = #{initValue}
AND (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) or T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')))
AND T1.PORTFOLIO_TYPE IN (#{portType}, #{portType1})

SELECT T1.FINPROD_MARKET_ID id, T1.FINPROD_NAME text, T1.FINPROD_NAME, T1.FINPROD_ID, T1.CALENDAR_ID, T1.CCY, T1.VDATE, T1.MDATE, T2.TYPE_6
,T2.TYPE_9 ,T2.TYPE_10 ,T2.TYPE_11
FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID
T1.FINPROD_TYPE2 = #{product}
and T1.FINPROD_MARKET_ID = #{initValue}
and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) or T1.FINPROD_NAME like concat('%',concat(#{search},'%')))
and T2.TYPE_6 = #{assetType1}
and T2.TYPE_9 = #{type9}
and T2.TYPE_10 = #{type10}
and T2.TYPE_11 = #{type11}

select TYPE_6 assetType1 from FIN_PRODUCT_TYPE
where 
FINPROD_ID = #{finprodId}

select ISSUE_AMT issueAmt from FIN_PRODUCT
where 
FINPROD_ID = #{finprodId}
